describe('Countdown Timer Interval Update', () => {
  beforeEach(() => {
    cy.visit('/timer');
  });

  it('should update countdown timer every second and display remaining time', () => {
    // Verify initial countdown timer is displayed
    cy.get('[data-testid="countdown-timer"]').should('be.visible');
    cy.get('[data-testid="countdown-timer"]').should('contain', '00:00:00');

    // Verify initial state
    cy.get('[data-testid="timer-value"]').should('contain', '00');
    cy.get('[data-testid="timer-minutes"]').should('contain', '00');
    cy.get('[data-testid="timer-seconds"]').should('contain', '00');

    // Wait for 1 second
    cy.wait(1000);

    // Verify timer has updated
    cy.get('[data-testid="countdown-timer"]').should('contain', '00:00:01');
    cy.get('[data-testid="timer-value"]').should('contain', '00');
    cy.get('[data-testid="timer-minutes"]').should('contain', '00');
    cy.get('[data-testid="timer-seconds"]').should('contain', '01');

    // Wait for another second
    cy.wait(1000);

    // Verify timer has updated again
    cy.get('[data-testid="countdown-timer"]').should('contain', '00:00:02');
    cy.get('[data-testid="timer-value"]').should('contain', '00');
    cy.get('[data-testid="timer-minutes"]').should('contain', '00');
    cy.get('[data-testid="timer-seconds"]').should('contain', '02');

    // Wait for 5 seconds
    cy.wait(5000);

    // Verify timer has reached 0
    cy.get('[data-testid="countdown-timer"]').should('contain', '00:00:05');
    cy.get('[data-testid="timer-value"]').should('contain', '00');
    cy.get('[data-testid="timer-minutes"]').should('contain', '00');
    cy.get('[data-testid="timer-seconds"]').should('contain', '05');

    // Verify countdown ends
    cy.get('[data-testid="countdown-timer"]').should('contain', '00:00:00');
    cy.get('[data-testid="timer-value"]').should('contain', '00');
    cy.get('[data-testid="timer-minutes"]').should('contain', '00');
    cy.get('[data-testid="timer-seconds"]').should('contain', '00');
  });

  it('should handle interval reset and continue updating', () => {
    // Verify initial countdown timer is displayed
    cy.get('[data-testid="countdown-timer"]').should('be.visible');
    cy.get('[data-testid="countdown-timer"]').should('contain', '00:00:00');

    // Wait for 3 seconds
    cy.wait(3000);

    // Verify timer has updated
    cy.get('[data-testid="countdown-timer"]').should('contain', '00:00:03');

    // Verify timer is still running
    cy.get('[data-testid="timer-value"]').should('contain', '00');
    cy.get('[data-testid="timer-minutes"]').should('contain', '00');
    cy.get('[data-testid="timer-seconds"]').should('contain', '03');

    // Click reset button
    cy.get('[data-testid="reset-button"]').click();

    // Verify timer resets
    cy.get('[data-testid="countdown-timer"]').should('contain', '00:00:00');
    cy.get('[data-testid="timer-value"]').should('contain', '00');
    cy.get('[data-testid="timer-minutes"]').should('contain', '00');
    cy.get('[data-testid="timer-seconds"]').should('contain', '00');

    // Wait for 2 seconds
    cy.wait(2000);

    // Verify timer has updated after reset
    cy.get('[data-testid="countdown-timer"]').should('contain', '00:00:02');
    cy.get('[data-testid="timer-value"]').should('contain', '00');
    cy.get('[data-testid="timer-minutes"]').should('contain', '00');
    cy.get('[data-testid="timer-seconds"]').should('contain', '02');

    // Verify timer continues to update
    cy.wait(1000);

    // Verify timer has updated again
    cy.get('[data-testid="countdown-timer"]').should('contain', '00:00:03');
    cy.get('[data-testid="timer-value"]').should('contain', '00');
    cy.get('[data-testid="timer-minutes"]').should('contain', '00');
    cy.get('[data-testid="timer-seconds"]').should('contain', '03');
  });
});
